B.aGA=new A.ep("Her mekan analizi 1 kredi harcar",null)
B.aGz=new A.ep("Ek kredi uygulama i\xe7i sat\u0131n alma ile edinilebilir",null)
B.aGy=new A.ep("Sat\u0131n al\u0131nan krediler iade edilemez",null)
B.aJX=new A.iG("Kabul Edilebilir Kullan\u0131m",null)
B.aIA=new A.ii("Uygulamay\u0131 yaln\u0131zca ki\u015fisel mekan analizi ama\xe7l\u0131 kullanabilirsiniz. A\u015fa\u011f\u0131daki davran\u0131\u015flar yasakt\u0131r:",null)
B.aGx=new A.ep("Uygulamay\u0131 k\xf6t\xfcye kullanmak veya ba\u015fkalar\u0131n\u0131n kullan\u0131m\u0131n\u0131 engellemek",null)
B.aGq=new A.ep("Otomatik botlar veya scraper kullanmak",null)
B.aGt=new A.ep("Uygulamay\u0131 s\u0131nav s\u0131ras\u0131nda kopya \xe7ekmek i\xe7in kullanmak",null)
